ReplacementContent:
"                                          {barData.map((d, idx) => {
                                            const heightPercent = 100 - getYCoordinate(d.total, ticks);
                                            return (
                                              <div key={idx} className="flex-1 flex flex-col items-center justify-end h-full relative group max-w-[28px]">
                                                <div 
                                                  className="w-full bg-[#8b5cf6] rounded-t-sm z-10 transition-all hover:bg-[#a78bfa] cursor-pointer min-h-[1px] relative" 
                                                  style={{ height: `${d.total > 0 ? Math.max(1, heightPercent) : 0}%` }}
                                                >
                                                  {/* Tooltip */}
                                                  <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-1.5 hidden group-hover:block bg-slate-900 text-white text-[9px] font-bold py-1 px-1.5 rounded shadow-lg whitespace-nowrap z-50">
                                                    {formatDateLabel(d.day, d.isMonth)}: {config.currency} {parseFloat(d.total || 0).toFixed(2)}
                                                  </div>
                                                </div>
                                              </div>
                                            );
                                          })}
                                       </div>"

